import GC from "./guitar.json";
import UC from "./ukulele.json"

const guitarChords = GC.chords;
const ukuleleChords = UC.chords;

interface GetChordLibraryKeyProps {
    rootNote: string;
    instrument?: "guitar" | "uke" | "bariuke"; 
}

/**
 * Chord library has some strange standard for naming chords
 * It goes C, Csharp, D, Eb, E, F, Fsharp, G, Ab, A, Bb, B for guitar
 * and A, Ab, B, Bb, C, D, Db, E, Eb, F, G, Gb for ukulele
 * @param {string} rootNote
 * @param {"guitar"|"uke"|"bariuke"} instrument
 */
export const getChordLibraryKey = ({rootNote, instrument = "guitar"}: GetChordLibraryKeyProps)  => {

    console.log("Get chord library key", rootNote, instrument)

    let finalNote;
    if (instrument === "guitar") {

        const notes = ["C", "Csharp", "D", "Eb", "E", "F", "Fsharp", "G", "Ab", "A", "Bb", "B"];
        if (notes.includes(rootNote)) {
            finalNote = rootNote;
        } else {
            switch (rootNote) {
                case "C#":
                    finalNote = "Csharp";
                    break;
                case "Db":
                    finalNote = "Csharp";
                    break;
                case "D#":
                    finalNote = "Eb";
                    break;
                case "F#":
                    finalNote = "Fsharp";
                    break;
                case "G#":
                    finalNote = "Ab";
                    break;
                case "A#":
                    finalNote = "Bb";
                    break;
                default:
                    finalNote = null;
            }
        }
    } else {
        const notes = ["Ab", "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G"];
        if (notes.includes(rootNote)) {
            finalNote = rootNote;
        } else {
            switch (rootNote) {
                case "C#":
                    finalNote = "Db";
                    break;
                case "D#":
                    finalNote = "Eb";
                    break;
                case "F#":
                    finalNote = "Gb";
                    break;
                case "G#":
                    finalNote = "Ab";
                    break;
                case "A#":
                    finalNote = "Bb";
                    break;
                default:
            }
        }
        if (finalNote && instrument === "bariuke") {
            // transpose 5 steps up
            // eg C becomes G
            // get position of finalNote in notes
            const semitones = 5;
            const startingIndex = notes.indexOf(finalNote);

            if (startingIndex === -1) {
                console.error("Note not found in the array!");
                return;
            }

            let targetIndex = (startingIndex + semitones) % notes.length;

            // If the result is negative, we add the length of the array to make sure it wraps around correctly
            if (targetIndex < 0) targetIndex += notes.length;

            console.log("Final Note", finalNote, "Target Index", targetIndex, "Target Note", notes[targetIndex])
            // return note at newIndex
            finalNote = notes[targetIndex];
        }
    }

    console.log(JSON.stringify({
        rootNote,
        instrument,
        finalNote,
    }))
    return finalNote;
};

/**
 * Validates a chord object exists in the chord library and returns it if found
 * @param {string | object} chordInput 
 */
export function validateChord(
    chordInput: string | { findChord: string, instrument?: "guitar" | "uke" | "bariuke" }
) {
    let findChord: string;
    let instrument: "guitar" | "uke" | "bariuke";

    if (typeof chordInput === "string") {
        findChord = chordInput;
        instrument = "guitar"; // Default instrument
    } else {
        findChord = chordInput.findChord;
        instrument = chordInput.instrument || "guitar"; // Use provided instrument or default
    }

    let chordLetter = findChord[0];
    // chordLetter must be musical note
    if (!chordLetter.match(/[A-G]/)) {
        return null;
    }

    let isAccidental = false;
    // is flat or sharp
    if (findChord[1] === "#" || findChord[1] === "b") {
        chordLetter += findChord[1];
        isAccidental = true;
    }

    let suffix = findChord.slice(isAccidental ? 2 : 1);
    if (suffix === "") {
        suffix = "major";
    }
    if (suffix === "m") {
        suffix = "minor";
    }
    if (suffix === "aug5") {
        suffix = "aug";
    }

    const chordLibraryKey = getChordLibraryKey({ rootNote: chordLetter, instrument });

    if (!chordLibraryKey) {
        return null;
    }

    const chordLibrary = instrument === "guitar" ? guitarChords : ukuleleChords;

    const chord = chordLibrary[chordLibraryKey as keyof typeof chordLibrary]?.find((chord) => chord.suffix === suffix)?.positions[0];

    if (!chord) {
        return null;
    }

    return chord;

}
