import findLines from "./line/findLines";
import findChunks from "./chunk/findChunks";
import createHtml from "./output/createHtml";
import Chord from "./ChordLib/Chord"
import { validateChord } from "./ChordLib/validateChord";
import instruments from "./ChordLib/instruments";
import { uniqueChords } from "./ChordLib/uniqueChords";

export const generateLyricSheet = (text: string, html: HTMLElement) => {
            const lines = findLines(text);
            const chunks = findChunks(lines);
            const styled = createHtml(chunks);
            html.appendChild(styled);
};

export {
     Chord,
     validateChord,
     instruments,
     uniqueChords,
}
