import { validateChord } from "./validateChord";

/**
 * Returns a unique set of chords from a lyrics string
 * @param {string} lyrics 
 * @returns {string[]} 
 */
export const uniqueChords = (lyrics:string) => {
  const chords : string[] = [];
  lyrics.split("\n").forEach((line) => {
    const numSpaces = line.split(" ").length - 1;
    const spaceToContentRatio = numSpaces / line.length;
    if (spaceToContentRatio > 0.3) {
      // this is a chord line
      `${line}  `.split(" ").forEach((word) => {
        if (word.trim().length > 0) {
          console.log("chord challenge", word.trim())
          if (validateChord(word.trim()) !== null)
          {
            chords.push(word.trim());
          }
        }
      });
    }
  });
  // return unique set of chords
  // sorted by most frequent first
  const finalChords = [...new Set(chords.map((chord) => chord.trim()))];
  console.log({ finalChords });
  return finalChords;
};
